import{_ as s,o as a,c as n,S as l}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"ELK收集Docker项目的日志","description":"","frontmatter":{"title":"ELK收集Docker项目的日志","date":"2021-06-14 11:21","comments":true,"archives":2021,"tags":["ELK docker"]},"headers":[],"relativePath":"posts/2021-06-14-elk-docker/index.md","filePath":"posts/2021/2021-06-14-elk-docker.md"}'),p={name:"posts/2021-06-14-elk-docker/index.md"};function o(r,e,c,t,i,d){return a(),n("div",null,[...e[0]||(e[0]=[l(`<p>现在主流的项目部署都是采用 docker 部署了，一般项目使用 <code>STDOUT</code> 输出的日志都被 docker 来收集和保存。我们需要使用著名的 <a href="https://www.elastic.co/what-is/elk-stack" target="_blank" rel="noreferrer">ELK</a> 来分析日志，所以如何部署 ELK 并且把 docker 的日志转发给 ELK 呢？ 这就是本篇文章我们需要解决的问题。</p><h2 id="搭建-elk" tabindex="-1">搭建 ELK <a class="header-anchor" href="#搭建-elk" aria-label="Permalink to &quot;搭建 ELK&quot;">​</a></h2><p>既然我们使用 docker 进行部署，那我们当然也要使用 docker 部署 ELK。<a href="https://github.com/deviantony/docker-elk" target="_blank" rel="noreferrer">docker-elk</a> 是一个配置好的项目，我们可以基于这个项目迅速搭建起一个 ELK 项目。说实话， ELK 项目非常消耗内存，所以至少保证机器有 4GB 内存，否则可能会宕机。搭建好 ELK 之后，记得按照教程重新设置密码。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>$ docker-compose exec -T elasticsearch bin/elasticsearch-setup-passwords auto --batch</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>初始化密码之后，并修改 <code>kibana</code> 和 <code>logstash</code> 的配置文件更新密码。最后再重启这两个服务：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>$ docker-compose restart kibana logstash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="使用-gelf-收集日志" tabindex="-1">使用 GELF 收集日志 <a class="header-anchor" href="#使用-gelf-收集日志" aria-label="Permalink to &quot;使用 GELF 收集日志&quot;">​</a></h2><p><a href="https://docs.graylog.org/en/4.0/pages/gelf.html" target="_blank" rel="noreferrer">GELF</a> 是一个经典的日志格式并且 docker 原生支持这个格式，首先我们需要配置 <code>logstash</code> 采取这个格式来收集日志。</p><p>修改 <code>logstash/pipeline/logstash.conf</code> 文件的 input 部分：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>input {</span></span>
<span class="line"><span>	beats {</span></span>
<span class="line"><span>		port =&gt; 5044</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	gelf {</span></span>
<span class="line"><span>		port =&gt; 5000</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>这样收集 <code>gelf</code> 的端口就是 <code>5000</code> 默认使用 UDP 格式。修改配置之后别忘了重启 <code>logstash</code>。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>$ docker-compose restart logstash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>接下来实际项目要把日志转发到 <code>ELK</code> 上，如果我们使用 <code>docker-compose.yml</code> 需要在当前的 <code>service</code> 上添加 <code>logging</code> 相关的配置：</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#22863A;">logging</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#22863A;">  driver</span><span style="color:#24292E;">: </span><span style="color:#032F62;">gelf</span></span>
<span class="line"><span style="color:#22863A;">  options</span><span style="color:#24292E;">:</span></span>
<span class="line"><span style="color:#22863A;">    gelf-address</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&#39;udp://0.0.0.0:5000&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>如果你的 ELK 和 实际项目并不是在同一台主机上，记得修改 <code>0.0.0.0</code> 成相应的主机名或 IP 地址。这样配置之后就可以在 <code>kibana</code> 上查看收集到的日志了。 不过要记得配置 <code>Index patterns</code> 然后在 <code>Discover</code> 界面上就能看到日志记录了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>ELK 收集 docker 日志并不是很复杂，但是摸索的时候很难调试，例如 ELK 配置了 <code>gelf</code> 方法收集日志，但却找不到好的方法来测试这个接口是否正常。 我只是通过 <code>nmap</code> 命令来检测 5000 端口是否开放，并不知道是否正常运行。</p><p>扫描当前主机的 UDP 端口：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>nmap -sU 0.0.0.0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>启动项目的 docker 的时候还出现了警告信息 <code>warning: no logs are available with the &#39;gelf&#39; log driver</code> 为了这个问题我查了半天，但发现 这个信息即使出现了也可以正常收集。浪费了不少时间。最终的解决方案总是很简单，但查找的过程中难免绕弯路。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://ibm-cloud-architecture.github.io/b2m-nodejs/logging/" target="_blank" rel="noreferrer">https://ibm-cloud-architecture.github.io/b2m-nodejs/logging/</a></p><p><a href="https://www.nginx.com/blog/using-free-ssltls-certificates-from-lets-encrypt-with-nginx/" target="_blank" rel="noreferrer">Using Free Let’s Encrypt SSL/TLS Certificates with NGINX</a></p>`,23)])])}const g=s(p,[["render",o]]);export{u as __pageData,g as default};
